import React, { useRef, useState, useEffect } from "react";
import "./VideoCarousel.css";

export default function VideoCarousel({ videoList }) {
  const videos = videoList || [
    "/assets/banner1.mp4",
    "/assets/banner2.mp4",
    "/assets/banner3.mp4",
    "/assets/banner4.mp4",
  ];

  const [index, setIndex] = useState(0);
  const [fade, setFade] = useState(false);
  const [isPlaying, setIsPlaying] = useState(true);
  const videoRef = useRef(null);

  // Auto slide
  useEffect(() => {
    const timer = setInterval(() => handleNext(), 6000);
    return () => clearInterval(timer);
  }, [index]);

  const handleNext = () => {
    setFade(true);
    setTimeout(() => {
      setIndex((prev) => (prev + 1) % videos.length);
      setFade(false);
      setIsPlaying(true); // resume autoplay on next
    }, 500);
  };

  const handlePrev = () => {
    setFade(true);
    setTimeout(() => {
      setIndex((prev) => (prev - 1 + videos.length) % videos.length);
      setFade(false);
      setIsPlaying(true);
    }, 500);
  };

  // 🔹 Toggle play/pause
  const togglePlay = () => {
    const vid = videoRef.current;
    if (!vid) return;

    if (vid.paused) {
      vid.play();
      setIsPlaying(true);
    } else {
      vid.pause();
      setIsPlaying(false);
    }
  };

  // Auto play when video changes
  useEffect(() => {
    if (videoRef.current) {
      videoRef.current.play().catch(() => {});
      setIsPlaying(true);
    }
  }, [index]);

  return (
    <div className="video-banner-container">
      <video
        ref={videoRef}
        key={videos[index]}
        src={videos[index]}
        className={`banner-video ${fade ? "fade-out" : "fade-in"}`}
        muted
        autoPlay
        loop
        playsInline
        controls={false}
      />

      <button className="vc-btn prev" onClick={handlePrev}>⟨</button>
      <button className="vc-btn next" onClick={handleNext}>⟩</button>

      <button className="play-overlay" onClick={togglePlay}>
        {isPlaying ? "❚❚" : "►"}
      </button>

      <div className="video-index">{index + 1}/{videos.length}</div>
    </div>
  );
}
